using TMPro;
using UnityEngine;

namespace AimLink
{
    /// <summary>
    /// The two HUD typefaces, loaded from Resources/AimLink (generated by AimLinkSetup from the TTFs in
    /// Assets/AimLink/Fonts). Mono = Share Tech Mono for readouts, Label = Rajdhani for captions.
    /// Falls back to TMP's default font if the assets are missing.
    /// </summary>
    public static class AimLinkFonts
    {
        static TMP_FontAsset _mono, _label;
        static bool _loaded;

        public static TMP_FontAsset Mono { get { Load(); return _mono; } }
        public static TMP_FontAsset Label { get { Load(); return _label; } }

        // Readouts must look the same on every headset language: "4.27 m" and "19:52:49", never "4,27" or "19.52.49".
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        static void UseInvariantCulture()
        {
            var culture = System.Globalization.CultureInfo.InvariantCulture;
            System.Globalization.CultureInfo.DefaultThreadCurrentCulture = culture;
            System.Globalization.CultureInfo.CurrentCulture = culture;
        }

        static void Load()
        {
            if (_loaded) return;
            _loaded = true;
            _mono = Resources.Load<TMP_FontAsset>("AimLink/AimLinkMono");
            _label = Resources.Load<TMP_FontAsset>("AimLink/AimLinkLabel");
        }

        public static void ApplyMono(TMP_Text text)
        {
            if (Mono != null) text.font = Mono;
        }

        /// <summary>Caption style: Rajdhani, wide letter spacing.</summary>
        public static void ApplyLabel(TMP_Text text)
        {
            if (Label != null) text.font = Label;
            text.characterSpacing = 12f;
        }
    }
}
